    public static synchronized void register(Application app) {
        if (registered) return;
        registered = true;
        GraphicsCompat.initialize(app);
        app.registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks() {
            private final Map<Activity, Watcher> watchers = new WeakHashMap<>();
            public void onActivityCreated(Activity a, Bundle b) {}
            public void onActivityStarted(Activity a) {}
            public void onActivityResumed(Activity a) {
                if (!english(a) || watchers.containsKey(a)) return;
                View root = a.findViewById(android.R.id.content);
                if (root == null) return;
                Watcher watcher = new Watcher(a, root);
                watchers.put(a, watcher);
                root.getViewTreeObserver().addOnGlobalLayoutListener(watcher);
                root.getViewTreeObserver().addOnScrollChangedListener(watcher);
                watcher.onGlobalLayout();
            }
            public void onActivityPaused(Activity a) {
                Watcher watcher = watchers.remove(a);
                if (watcher != null) watcher.dispose();
            }
            public void onActivityStopped(Activity a) {}
            public void onActivitySaveInstanceState(Activity a, Bundle b) {}
            public void onActivityDestroyed(Activity a) {
                Watcher watcher = watchers.remove(a);
                if (watcher != null) watcher.dispose();
            }
        });
    }
    /** Display-only hook for Compose Material Text; never changes route data or text-field models. */
    public static String localizeUiText(String value) {
        if (value == null || !GraphicsCompat.isEnglish()) return value;
        synchronized (UI_CACHE) {
            String cached = UI_CACHE.get(value);
            if (cached != null) return cached;
        }
        String result = value;
        String[] directions = GATE_DIRECTIONS;
        String[] names = GATE_NAMES;
        for (int i = 0; i < directions.length; i++) {
            result = result.replace(directions[i] + "改札口", names[i] + " gate")
                .replace(directions[i] + "改札", names[i] + " gate");
        }
        if (result.contains("出口")) result = PATTERN_0.matcher(result).replaceAll("Exit $1");
        if (result.contains("入口")) result = PATTERN_1.matcher(result).replaceAll("Entrance $1");
        if (result.indexOf(':') >= 0) {
            if (result.contains("Depart") || result.contains("Arrive")) result = PATTERN_2.matcher(result).replaceAll("$1 $2");
            if (result.contains("dep.")) result = PATTERN_3.matcher(result).replaceAll("$1 D");
            if (result.contains("arr.")) result = PATTERN_4.matcher(result).replaceAll("$1 A");
        }
        if (result.equals("改札") || result.equals("改札口")) result = "Ticket gate";
        synchronized (UI_CACHE) { UI_CACHE.put(value, result); }
        return result;
    }
    private static boolean english(Activity a) {
        return "en".equals(a.getResources().getConfiguration().getLocales().get(0).getLanguage());
    }
    private static final class Watcher implements ViewTreeObserver.OnGlobalLayoutListener, ViewTreeObserver.OnScrollChangedListener, Runnable {
        private final WeakReference<Activity> activity;
        private final View root;
        private boolean queued;
        private long lastScroll;
        private boolean disposed;
        Watcher(Activity a, View root) { activity = new WeakReference<>(a); this.root = root; }
        public void onGlobalLayout() {
            if (!queued && !disposed) { queued = true; root.postDelayed(this, 100); }
        }
        public void onScrollChanged() {
            lastScroll = SystemClock.uptimeMillis();
            onGlobalLayout();
        }
        public void run() {
            queued = false;
            Activity a = activity.get();
            if (disposed || a == null || a.isDestroyed() || !english(a)) return;
            long wait = 160 - (SystemClock.uptimeMillis() - lastScroll);
            if (wait > 0) { queued = true; root.postDelayed(this, wait); return; }
            translate(root, 0);
        }
        void dispose() {
            disposed = true;
            root.removeCallbacks(this);
            if (root.getViewTreeObserver().isAlive()) root.getViewTreeObserver().removeOnGlobalLayoutListener(this);
            if (root.getViewTreeObserver().isAlive()) root.getViewTreeObserver().removeOnScrollChangedListener(this);
        }
    }
    private static void translate(View view, int depth) {
        if (depth > 40 || view.getVisibility() != View.VISIBLE || view instanceof EditText) return;
        CharSequence description = view.getContentDescription();
        if (description != null) {
            String translated = TEXT.get(description.toString());
            if (translated != null && !translated.contentEquals(description)) view.setContentDescription(translated);
        }
        if (view instanceof TextView) {
            TextView textView = (TextView) view;
            CharSequence current = textView.getText();
            String last = LAST_TEXT.get(textView);
            if (current != null && (last == null || !last.contentEquals(current))) {
                String before = current.toString();
                String after = TEXT.get(before);
                if (after == null) {
                    // Normalize displayed date/time units, not the underlying formatter or data.
                    after = before;
                    if (after.indexOf('年') >= 0) after = PATTERN_5.matcher(after).replaceAll("$1-$2-$3");
                    if (after.indexOf('月') >= 0) after = PATTERN_6.matcher(after).replaceAll("$1/$2");
                    if (after.indexOf('時') >= 0) after = PATTERN_7.matcher(after).replaceAll("$1:$2");
                    if (after.indexOf('発') >= 0) after = PATTERN_8.matcher(after).replaceAll("$1 dep.");
                    if (after.indexOf('着') >= 0) after = PATTERN_9.matcher(after).replaceAll("$1 arr.");
                    String[] jp = DAYS_JP;
                    String[] en = DAYS_EN;
                    for (int i = 0; i < jp.length; i++) after = after.replace(jp[i], en[i]);
                }
                after = localizeUiText(after);
                if (!before.equals(after)) textView.setText(after);
                LAST_TEXT.put(textView, after);
            }
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int i = 0; i < group.getChildCount(); i++) translate(group.getChildAt(i), depth + 1);
        }
    }
